const lessons=[{"sentences":[{"speaker":"A","text":"Pine Valley campsite bookings how can I help you today.","position":1,"audioStartSeconds":0,"audioEndSeconds":3.7413333333333334},{"speaker":"B","text":"Hello I would like to reserve a pitch for next weekend please.","position":2,"audioStartSeconds":3.941333333333333,"audioEndSeconds":8.029833333333332},{"speaker":"A","text":"We have standard pitches and premium pitches with electricity available.","position":3,"audioStartSeconds":8.229833333333334,"audioEndSeconds":13.012333333333334},{"speaker":"B","text":"Let us take a standard pitch because we prefer a quiet grassy field.","position":4,"audioStartSeconds":13.212333333333333,"audioEndSeconds":17.749208333333332},{"speaker":"A","text":"That area is very peaceful although power is not included.","position":5,"audioStartSeconds":17.949208333333335,"audioEndSeconds":22.24041666666667},{"speaker":"B","text":"We brought portable batteries so we do not need electricity anyway.","position":6,"audioStartSeconds":22.440416666666668,"audioEndSeconds":26.847625},{"speaker":"A","text":"Wonderful and what is your intended arrival date for this trip.","position":7,"audioStartSeconds":27.047625,"audioEndSeconds":31.081125},{"speaker":"B","text":"We planned to arrive on Friday evening after finishing our work shifts.","position":8,"audioStartSeconds":31.281125,"audioEndSeconds":36.11358333333333},{"speaker":"A","text":"Our office closes early on Friday so you should arrive on Saturday morning.","position":9,"audioStartSeconds":36.313583333333334,"audioEndSeconds":41.15895833333333},{"speaker":"B","text":"Saturday morning works well because we can travel when the traffic is lighter.","position":10,"audioStartSeconds":41.358958333333334,"audioEndSeconds":46.07545833333333},{"speaker":"A","text":"You can also book our shuttle bus if you want station transport.","position":11,"audioStartSeconds":46.27545833333333,"audioEndSeconds":50.46525},{"speaker":"B","text":"We will drive our own car instead of taking the shuttle bus.","position":12,"audioStartSeconds":50.66525,"audioEndSeconds":54.887458333333335}],"questions":[{"prompt":"Chosen pitch type: ______","answer":"standard pitch","evidenceSentence":4,"evidence":"Let us take a standard pitch","explanation":"Khách hàng chọn 'standard pitch' (bãi cắm trại tiêu chuẩn) sau khi nghe tư vấn."},{"prompt":"Excluded utility: ______","answer":"power","evidenceSentence":5,"evidence":"power is not included","explanation":"Khu vực tiêu chuẩn không bao gồm nguồn điện trực tiếp."},{"prompt":"Brought power item: ______","answer":"portable batteries","evidenceSentence":6,"evidence":"We brought portable batteries","explanation":"Họ mang theo pin dự phòng thay vì dùng ổ cắm điện."},{"prompt":"Original arrival time: ______","answer":"Friday evening","evidenceSentence":8,"evidence":"arrive on Friday evening","explanation":"Thời gian dự định ban đầu là tối thứ Sáu."},{"prompt":"Revised arrival time: ______","answer":"Saturday morning","evidenceSentence":9,"evidence":"arrive on Saturday morning","explanation":"Lịch hẹn đã được đổi sang sáng thứ Bảy."},{"prompt":"Rejected transport service: ______","answer":"shuttle bus","evidenceSentence":12,"evidence":"instead of taking the shuttle bus","explanation":"Họ từ chối dịch vụ xe buýt đưa đón để tự lái xe."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
